import {presets,matrix,solve,verify,linearCandidate} from './pga300-core.mjs?v=0.4.1';
import {SerialBridge,PGA300,PGA_GAINS,TGAINS,decodeEEPROM,prepareLinear,prepareSettings,recommendGain,hex,crc8,identifyAdapter,prepareRestore,registerRows} from './pga300-hardware.mjs?v=0.4.1';
import {EvmBridge} from './pga300-evm.mjs?v=0.4.1';
import {q14Candidate,compareReference,outputCalibration,verifyAnalog,decodeDiag} from './pga300-test-tools.mjs?v=0.4.1';
document.body.innerHTML="<div class=\"wrap\"><header class=\"top\">\n<div class=\"brand\"><div class=\"logo\" aria-hidden=\"true\">TI</div><div><div class=\"eyebrow\">PGA300 · Texas Instruments · v0.4.1</div><h1>Kalibrierassistent</h1></div></div>\n<div class=\"live-overview\" role=\"group\" aria-label=\"Live-Sensorwerte: zuerst Temperatur, danach Druck und Sensorwert\">\n  <div class=\"live-kpi\" title=\"TADC · manuell erfasster Rohwert; keine Live-Abfrage.\"><span class=\"live-kpi-label\">TADC</span><span class=\"live-kpi-reading\" id=\"liveAdcT\">—</span><span class=\"live-kpi-unit\">Digits</span></div>\n  <div class=\"live-kpi\" title=\"Externe Referenztemperatur; keine Chipmessung.\"><span class=\"live-kpi-label\">Referenztemperatur</span><span class=\"live-kpi-reading\" id=\"liveTempC\">—</span><span class=\"live-kpi-unit\" id=\"liveTempUnit\">°C · Referenz</span></div>\n  <div class=\"live-kpi live-kpi-pressure-start\" title=\"PADC · manuell erfasster Rohwert.\"><span class=\"live-kpi-label\">PADC <span id=\"liveAdcAlert\" class=\"live-alert\" hidden>!</span></span><span class=\"live-kpi-reading\" id=\"liveAdcS\">—</span><span class=\"live-kpi-unit\">Digits</span></div>\n  <div class=\"live-kpi\" title=\"Berechneter Modell-DAC; kein Chip-Readback.\"><span class=\"live-kpi-label\">DAC-Modell</span><span class=\"live-kpi-reading\" id=\"liveDspS\">—</span><span class=\"live-kpi-unit\">Codes</span></div>\n  <div class=\"live-kpi live-kpi-primary\"><span class=\"live-kpi-label\">Referenzdruck</span><span class=\"live-kpi-reading\" id=\"livePressure\">—</span><span class=\"live-kpi-unit live-pressure-meta\"><span id=\"livePressureUnit\">—</span> <button type=\"button\" id=\"livePressureInfo\" class=\"live-pressure-info\" hidden aria-label=\"Berechnungsdetails\" aria-describedby=\"livePressureTooltip\">?</button><span id=\"livePressureTooltip\" class=\"live-pressure-tooltip\" role=\"tooltip\"></span></span></div>\n</div>\n<div class=\"live-connection\"><div class=\"connection-actions\"><button type=\"button\" id=\"guidedHomeTop\" class=\"settings-gear guided-home-top\" title=\"Zur geführten Aufgabenauswahl\">↩ Aufgabenauswahl</button><button type=\"button\" id=\"archiveOpen\" class=\"settings-gear\" title=\"Lokales Kalibrierarchiv durchsuchen\" hidden>▤ Archiv</button><button type=\"button\" id=\"verificationOpen\" hidden aria-hidden=\"true\" tabindex=\"-1\" title=\"Nachmessung öffnen\"></button><button type=\"button\" id=\"guidedLaunchTop\" class=\"settings-gear\" title=\"Zur geführten Ansicht wechseln\" aria-pressed=\"false\">◇ Geführt</button><button type=\"button\" id=\"settingsOpen\" class=\"settings-gear\" aria-expanded=\"false\" aria-controls=\"settingsPanel\" title=\"App-Einstellungen öffnen\">⚙ Einstellungen</button><span class=\"chip\"><span class=\"dot\" id=\"statusDot\"></span><span id=\"status\">Nicht verbunden · Offline</span></span><span class=\"live-meta\"><span class=\"live-meta-dot\" id=\"liveStateDot\"></span><span id=\"liveState\">Keine Live-Messung</span><span aria-hidden=\"true\">·</span><span id=\"liveLastRead\">—</span><span id=\"liveDiagnostic\" title=\"Manuelle Erfassung\" style=\"font-size:10px;opacity:.85\"></span></span></div></div>\n</header><section class=\"settings-panel\" id=\"settingsPanel\" hidden aria-label=\"App-Einstellungen\"><div class=\"settings-panel-head\"><div><strong>App-Einstellungen</strong><span>Darstellung und Messverhalten</span></div><button id=\"settingsClose\">Schliessen</button></div><div class=\"settings-body\"><section class=\"settings-group\"><h3>Darstellung</h3><div class=\"settings-fields\"><label>Farbmodus<select id=\"settingsTheme\"><option value=\"light\">Hell</option><option value=\"dark\">Dunkel</option></select></label><label>SSC<select id=\"chip\"><option value=\"pga300\">PGA300</option><option value=\"pga302\">PGA302</option><option value=\"pga305\">PGA305</option><option value=\"pga309\">PGA309</option></select></label></div><label class=\"toggle\"><input id=\"classicSetting\" type=\"checkbox\"> Klassische Ansicht (One-Pager)</label><label class=\"toggle\"><input id=\"expertMode\" type=\"checkbox\"> Expertenparameter</label></section><section class=\"settings-group\"><h3>Messung</h3><p>Hardware-Live-Abfrage über experimentelle OWI-Bridge. Kein automatischer Reconnect.</p></section><section class=\"settings-group\"><h3>Hilfen &amp; Tools</h3><p><a href=\"https://www.ti.com/lit/ds/symlink/pga300.pdf\" target=\"_blank\" rel=\"noopener\">PGA300 Datenblatt</a> · <a href=\"https://vadergit.github.io/SSC-Calibration-Studio/\" target=\"_blank\" rel=\"noopener\">SSC Calibration Studio</a></p></section></div></section>\n<div id=\"guidedWorkspace\"><div class=\"gw-shell\"><aside class=\"gw-sidebar\"><div class=\"gw-backlogo\"><span>◆</span> PGA300 · Geführter Abgleich</div><nav class=\"gw-sideitems\" id=\"steps\" aria-label=\"Kalibrierschritte\"></nav><div class=\"gw-sidebar-footer\">Die klassische Ansicht bleibt jederzeit erreichbar.<div style=\"margin-top:9px\">Testversion · EEPROM standardmässig gesperrt</div></div></aside><div class=\"gw-main\"><div class=\"gw-topline\"><span class=\"gw-kicker\" id=\"kicker\"></span><div class=\"gw-connection-top-actions\"><span class=\"gw-chipstatus is-offline\">Nicht verbunden</span><button id=\"connectTop\" class=\"gw-connection-link\">Verbindung &amp; Diagnose</button></div></div><div class=\"gw-progressbar\"><span id=\"progress\" style=\"width:0%\"></span></div><div class=\"gw-heading-row\"><div><h2 class=\"gw-title\" id=\"gwTitle\"></h2><p class=\"gw-desc\" id=\"gwDesc\"></p></div></div><p class=\"gw-alert\" id=\"notice\" role=\"status\" aria-live=\"polite\" hidden></p>\n<section id=\"gwPage0\" class=\"gw-page\" data-page=\"0\"><div class=\"gw-columns gw-six\"><button type=\"button\" class=\"gw-choice\" data-task=\"calibration\"><span class=\"gw-choice-icon\">◉</span><strong>Sensor neu abgleichen</strong><small>Von der Messung über die Modellprüfung bis zur Vorbereitung der EEPROM-Programmierung.</small></button><button type=\"button\" class=\"gw-choice\" data-task=\"alarms\"><span class=\"gw-choice-icon\">⚑</span><strong>Alarme und Fehler ändern</strong><small>Diagnose- und Fehlerreaktionen dokumentieren; Registerzugriff noch gesperrt.</small></button><button type=\"button\" class=\"gw-choice\" data-task=\"output\"><span class=\"gw-choice-icon\">↗</span><strong>Nur Ausgang ändern</strong><small>DAC-Zielwerte und Ausgangsbegrenzung planen.</small></button><button type=\"button\" class=\"gw-choice\" data-task=\"bridge\"><span class=\"gw-choice-icon\">▣</span><strong>Sensorbrücken-Rechner</strong><small>Brückennullpunkt, Spanne und Temperaturgang aus externen Messungen berechnen.</small></button><button type=\"button\" class=\"gw-choice\" data-task=\"inspect\"><span class=\"gw-choice-icon\">▤</span><strong>EEPROM / Diagnose</strong><small>EEPROM-Datei offline ansehen und den Hardwarestatus prüfen.</small></button><button type=\"button\" class=\"gw-choice\" data-task=\"testlog\"><span class=\"gw-choice-icon\">◷</span><strong>Test / Logging</strong><small>Externe Messwerte und Notizen zeitgestempelt erfassen und exportieren.</small></button><button type=\"button\" class=\"gw-choice\" data-task=\"verification\"><span class=\"gw-choice-icon\">↕</span><strong>Nachmessung</strong><small>Unabhängige Modellprüfung und Messfehler beurteilen.</small></button><button type=\"button\" class=\"gw-choice\" data-task=\"archive\"><span class=\"gw-choice-icon\">▥</span><strong>Archiv</strong><small>Frühere Abgleiche und Tests lokal speichern, suchen und exportieren.</small></button></div><div class=\"gw-alert\">Labor-Testversion · Hardwaremodus experimentell · OWI-Adapter erforderlich. Alternativ manuelle Messung oder Simulation.</div></section>\n<section id=\"tiTool1\" class=\"gw-page\" data-page=\"1\" hidden><h2>Verbindung und Sensor</h2><p class=\"muted\">PGA300 nutzt OWI über die Versorgung. Ein USB-UART allein ist keine geeignete OWI-Schnittstelle.</p><div class=\"gw-fields\"><label>Erfassungsmodus<select id=\"mode\"><option value=\"hardware\">Hardware · OWI v2 / TI USB2ANY</option><option value=\"manual\" selected>Manuelle Messwerte (offline)</option><option value=\"demo\">Simulation / synthetisch</option></select></label><label>Sensor-ID / Auftrag<input id=\"sensor\" placeholder=\"Optional\"></label><label>Adapter<select id=\"adapter\"><option value=\"esp32\">ESP32-C3 · USB Serial</option><option value=\"promicro\">Arduino Pro Micro · USB Serial</option><option value=\"evm\">TI PGAxxxEVM-034 · USB2ANY (lokale SDK-Bridge)</option></select></label></div><div class=\"gw-panel-actions\"><button id=\"hwConnect\" class=\"primary\">USB / OWI verbinden</button><button id=\"hwDisconnect\">Execution-Modus &amp; trennen</button><button id=\"hwRead\">EEPROM auslesen</button></div><p id=\"hwAdapterHelp\">ESP32 und Pro Micro: Web Serial, externes OWI-Frontend. TI: lokaler Windows-Dienst mit originaler USB2ANY.dll.</p><label class=\"check\"><input id=\"hwWriteGate\" type=\"checkbox\"> Experimentelle EEPROM-Schreibtests erlauben (entbehrlicher Testchip)</label><p id=\"hwState\" role=\"status\">Nicht verbunden</p><p><a href=\"./firmware/esp32c3_pga300/esp32c3_pga300.ino\" target=\"_blank\">ESP32-C3 Firmware v2 (Quellcode)</a> · <a href=\"./firmware/promicro_pga300/promicro_pga300.ino\" target=\"_blank\">Pro Micro Firmware v2</a> · <a href=\"./tools/usb2any_bridge.py\" target=\"_blank\">TI SDK-Bridge für Windows</a> · <a href=\"./docs/PGA300-OWI.md\" target=\"_blank\">Anschluss / Testanleitung</a></p><div class=\"gw-alert\">OWI benötigt einen externen Spannungsmodulator und Stromempfänger. Beim Verbinden wechselt der Sensor in den Konfigurationsmodus und der Analogausgang kann ausfallen. Nur am Prüfplatz verwenden.</div></section>\n<section id=\"gwPage1\" class=\"gw-page\" data-page=\"2\" hidden><h2>Messkonzept</h2><p class=\"muted\">Wähle die Druck- und Temperaturmatrix. Die vollständige dritte Ordnung benötigt mindestens 16 unabhängige Messungen.</p><div class=\"gw-preset-grid\"><button class=\"gw-preset\" data-preset=\"quick\"><strong>Schnell</strong><small>0–100 % · 2 Druckpunkte, ohne Temperaturkorrektur.</small></button><button class=\"gw-preset\" data-preset=\"tk0\"><strong>TK0 · 3 Punkte</strong><small>Nullpunkt-Temperaturgang und Druckspanne · ohne TKE.</small></button><button class=\"gw-preset\" data-preset=\"tke\"><strong>TK0 + TKE · 4 Punkte</strong><small>Nullpunkt und Empfindlichkeit temperaturabhängig kalibrieren.</small></button><button class=\"gw-preset\" data-preset=\"temperature\"><strong>Mit Temperatur</strong><small>2 Druckpunkte × 3 Temperaturstufen.</small></button><button class=\"gw-preset\" data-preset=\"custom\"><strong>Individuell</strong><small>3 Druckpunkte × 2 Temperaturstufen; anpassbar.</small></button><button class=\"gw-preset\" data-preset=\"full\"><strong>Volle TI-Kompensation</strong><small>4 Druckpunkte × 4 Temperaturen · 16 Koeffizienten.</small></button></div><div class=\"gw-fields\"><label>Druckpunkte<select id=\"pc\"><option>2</option><option>3</option><option>4</option><option>5</option></select></label><label>Temperaturstufen<select id=\"tc\"><option>1</option><option>2</option><option>3</option><option>4</option></select></label><label>Druckordnung<select id=\"po\"><option>1</option><option>2</option><option>3</option></select></label><label>Temperaturordnung<select id=\"to\"><option>0</option><option>1</option><option>2</option><option>3</option></select></label></div><div class=\"gw-fields\"><label>Temperaturmodell<select id=\"thermalFit\"><option value=\"full\">Vollständige Matrix</option><option value=\"tk0\">Nur TK0 · 3 Punkte</option></select></label></div><div id=\"concept\" class=\"gw-summary\"></div></section>\n<section id=\"gwPage2\" class=\"gw-page gw-setup-page\" data-page=\"3\" hidden><h2>Sensor und Zielwerte definieren</h2><div class=\"gw-fields\" id=\"sensorFields\"><label>Druck min<input id=\"min\" type=\"number\" value=\"0\" step=\"any\"></label><label>Druck max<input id=\"max\" type=\"number\" value=\"100\" step=\"any\"></label><label>Einheit<select id=\"unit\"><option>%</option><option>bar</option><option>mbar</option><option>kPa</option><option>MPa</option><option>psi</option></select></label><label>Referenztemperaturen (°C; mit Komma getrennt)<input id=\"temps\" value=\"25\"></label><label>DAC min (Code)<input id=\"dacLow\" type=\"number\" value=\"1638\" min=\"0\" max=\"16383\"></label><label>DAC max (Code)<input id=\"dacHigh\" type=\"number\" value=\"14745\" min=\"0\" max=\"16383\"></label><label>Ausgangsart (Planung)<select id=\"output\"><option>Spannung ratiometrisch</option><option>Spannung absolut</option><option>4–20 mA</option></select></label><label>Versorgung (V, dokumentarisch)<input id=\"vdd\" type=\"number\" value=\"5\" step=\"any\"></label></div><p class=\"muted\">Die DAC-Zielwerte sind frei gewählte Planungswerte, keine automatisch berechneten Spannungs- oder Stromwerte. Die Temperatur muss physisch am Sensor eingestellt werden.</p><button id=\"saveConfig\">Config exportieren</button> <label class=\"file\">Config importieren<input id=\"loadConfig\" type=\"file\" accept=\".json\"></label></section>\n<section id=\"gwPage3\" class=\"gw-page gw-afe-page\" data-page=\"4\" hidden><h2>AFE vorbereiten</h2><p>Verstärkung, ADC-Skalierung und Temperaturquelle müssen über den externen Messaufbau eingestellt und während der gesamten Messung konstant gehalten werden.</p><div class=\"gw-fields\"><label>P Gain (V/V, dokumentarisch)<input id=\"pg\" type=\"number\" min=\"0.001\" step=\"any\" placeholder=\"Gemessene Einstellung\"></label><label>T Gain (V/V, dokumentarisch)<input id=\"tg\" type=\"number\" min=\"0.001\" step=\"any\" placeholder=\"Gemessene Einstellung\"></label><label>Temperaturquelle<select id=\"ts\"><option>Intern</option><option>Extern</option></select></label><label>Samples pro Messpunkt (dokumentarisch)<input id=\"samples\" type=\"number\" min=\"1\" value=\"16\"></label></div><div class=\"gw-alert\">Im Hardwaremodus P-/T-Gain, Polarität, Brückenspeisung und Temperaturquelle temporär einstellen und rücklesen. Vor jeder Änderung werden die bisherigen Messpunkte verworfen.</div><div class=\"gw-tile\"><h3>AFE · Hardware</h3><div class=\"gw-fields\"><label>P Gain<select id=\"hwPG\"><option value=\"0\">5 V/V</option><option value=\"1\">5.48 V/V</option><option value=\"2\">5.97 V/V</option><option value=\"3\">6.56 V/V</option><option value=\"4\">7.02 V/V</option><option value=\"5\">8 V/V</option><option value=\"6\">9.09 V/V</option><option value=\"7\">10 V/V</option><option value=\"8\">10.53 V/V</option><option value=\"9\">11.11 V/V</option><option value=\"10\">12.5 V/V</option><option value=\"11\">13.33 V/V</option><option value=\"12\">14.29 V/V</option><option value=\"13\">16 V/V</option><option value=\"14\">17.39 V/V</option><option value=\"15\">18.18 V/V</option><option value=\"16\">19.05 V/V</option><option value=\"17\">20 V/V</option><option value=\"18\">22.22 V/V</option><option value=\"19\">25 V/V</option><option value=\"20\">30.77 V/V</option><option value=\"21\">36.36 V/V</option><option value=\"22\">40 V/V</option><option value=\"23\">44.44 V/V</option><option value=\"24\">50 V/V</option><option value=\"25\">57.14 V/V</option><option value=\"26\">66.67 V/V</option><option value=\"27\">80 V/V</option><option value=\"28\">100 V/V</option><option value=\"29\">133.33 V/V</option><option value=\"30\">200 V/V</option><option value=\"31\">400 V/V</option></select></label><label>T Gain<select id=\"hwTG\"><option value=\"0\">1.33 V/V</option><option value=\"1\">2 V/V</option><option value=\"2\">5 V/V</option><option value=\"3\">20 V/V</option></select></label><label>Brückenspeisung<select id=\"hwBridge\"><option value=\"0\">2.5 V</option><option value=\"1\">2.0 V</option><option value=\"2\">1.25 V</option></select></label><label>Temperaturquelle<select id=\"hwTemp\"><option value=\"3\">Intern</option><option value=\"0\">Extern differentiell</option></select></label><label class=\"check\"><input id=\"hwInv\" type=\"checkbox\"> P invertieren</label><label class=\"check\"><input id=\"hwTInv\" type=\"checkbox\"> T invertieren</label></div><div class=\"gw-panel-actions\"><button id=\"hwAFERead\">AFE auslesen</button><button id=\"hwAFEApply\" class=\"primary\">AFE im RAM übernehmen</button><button id=\"hwSample\">ADC messen</button><button id=\"hwLive\">Live starten</button></div><div class=\"gw-fields\"><label>ADC bei Minimaldruck<input id=\"hwLow\" type=\"number\"></label><label>ADC bei Maximaldruck<input id=\"hwHigh\" type=\"number\"></label></div><div class=\"gw-panel-actions\"><button id=\"hwLowCapture\">Minimaldruck messen</button><button id=\"hwHighCapture\">Maximaldruck messen</button><button id=\"hwGainRecommend\">Gain vorschlagen</button><button id=\"hwGainApplyAuto\">Gain-Vorschlag übernehmen</button></div><p id=\"hwGainAdvice\"></p><svg id=\"hwTrend\" viewBox=\"0 0 600 180\" width=\"100%\" role=\"img\" aria-label=\"PADC und TADC, letzte 120 Messwerte\"></svg><p id=\"hwADC\">PADC — · TADC —</p></div><label class=\"check\"><input id=\"afeConfirmed\" type=\"checkbox\"> AFE und Messaufbau geprüft bzw. für Simulation bestätigt.</label></section>\n<section id=\"gwPage4\" class=\"gw-page\" data-page=\"5\" hidden><h2>Messpunkte erfassen</h2><p id=\"capture\"></p><div class=\"gw-panel-actions\"><button id=\"hwCapture\" class=\"primary\">Nächsten Punkt vom SSC erfassen</button><button id=\"make\">Matrix erstellen / zurücksetzen</button><button id=\"demo\">Simulationsdaten laden</button><button id=\"calculate\" class=\"primary\">Koeffizienten berechnen</button></div><div class=\"scroll\"><table><thead><tr><th>Punkt</th><th>Druck</th><th>Temp. °C</th><th>DAC Soll</th><th>PADC</th><th>TADC</th><th>Fehler DAC</th></tr></thead><tbody id=\"measure\"></tbody></table></div></section><section id=\"gwPage5\" class=\"gw-page\" data-page=\"9\" hidden><h2>Koeffizienten berechnen</h2><div class=\"gw-panel-actions\"><button id=\"recalculate\" class=\"primary\">Koeffizienten berechnen</button></div><div id=\"fitResult\" hidden><div class=\"gw-summary\" id=\"fitMetrics\"></div><h3>Normalisierte Modellkoeffizienten</h3><p class=\"muted\">Gleitkomma-Modell, keine EEPROM-Registerwerte. P und T werden aus ADC-Codes auf einen numerisch günstigen Bereich skaliert.</p><div class=\"scroll\"><table><thead><tr><th>Koeffizient</th><th>Wert</th></tr></thead><tbody id=\"coeff\"></tbody></table></div><div class=\"gw-tile\"><h3>TC/NL · 16 Registerkandidaten</h3><p>Normierte Q14-Testrechnung. Abweichende h0-Skalierung in TI-Dokumenten; keine automatische EEPROM-Freigabe.</p><pre id=\"q14Result\"></pre><label>TI-Referenz importieren (JSON, h0…m3 als signed 16-bit)<input id=\"q14Ref\" type=\"file\" accept=\".json\"></label><pre id=\"q14Compare\"></pre></div><pre id=\"linear\"></pre></div></section>\n<section id=\"gwPage6\" class=\"gw-page\" data-page=\"6\" hidden><h2>Unabhängige Nachmessung</h2><p>Andere ADC-Punkte als für die Berechnung verwenden. Die Prüfung bewertet ausschliesslich das Modell, nicht einen programmierten Chip.</p><div class=\"gw-fields\"><label>Toleranz (DAC Codes)<input id=\"tol\" type=\"number\" min=\"0.001\" step=\"any\" value=\"16\"></label></div><div class=\"gw-panel-actions\"><button id=\"hwVerifyCapture\">Prüf-ADC vom SSC übernehmen</button><button id=\"addCheck\">Prüfpunkt hinzufügen</button><button id=\"demoCheck\">Synthetischen Prüfpunkt laden</button><button id=\"runCheck\" class=\"primary\">Prüfen</button></div><div class=\"scroll\"><table><thead><tr><th>PADC</th><th>TADC</th><th>DAC Soll</th><th>DAC tatsächlich (optional)</th><th>Ergebnis</th><th></th></tr></thead><tbody id=\"checks\"></tbody></table></div><div id=\"verification\"></div><svg id=\"graph\" viewBox=\"0 0 600 210\" role=\"img\" aria-label=\"Modellfehler der Prüfpunkte\"></svg></section>\n<section id=\"gwPage7\" class=\"gw-page\" data-page=\"7\" hidden><h2>Ausgang konfigurieren</h2><p id=\"outSummary\"></p><div class=\"gw-fields\" id=\"outputFields\"></div><div class=\"gw-tile\"><h3>Physische Ausgangskalibrierung</h3><p>Zwei DAC-Testwerte mit externem Multimeter messen. Einheit durchgehend V oder mA. Aus der realen Kennlinie werden Zielcodes berechnet.</p><div class=\"gw-fields\"><label>Code 1<input id=\"outC1\" type=\"number\" value=\"1638\"></label><label>Ist 1<input id=\"outA1\" type=\"number\" step=\"any\"></label><label>Code 2<input id=\"outC2\" type=\"number\" value=\"14745\"></label><label>Ist 2<input id=\"outA2\" type=\"number\" step=\"any\"></label><label>Soll min<input id=\"outGoal1\" type=\"number\" step=\"any\" value=\"0.5\"></label><label>Soll max<input id=\"outGoal2\" type=\"number\" step=\"any\" value=\"4.5\"></label></div><div class=\"gw-panel-actions\"><button id=\"outTest1\">Code 1 ausgeben</button><button id=\"outTest2\">Code 2 ausgeben</button><button id=\"outFit\">Zielcodes berechnen</button><button id=\"outUse\">Zielcodes übernehmen</button></div><p id=\"outFitResult\"></p></div><div class=\"gw-tile\"><h3>Ausgang · RAM / DAC-Test</h3><div class=\"gw-fields\"><label>Ausgangsstufe<select id=\"hwOutStage\"><option value=\"8\">4–20 mA</option><option value=\"4\">Spannung · Gain 2</option><option value=\"2\">Spannung · Gain 4</option><option value=\"6\">Spannung · Gain 6.67</option><option value=\"1\">Spannung · Gain 10</option></select></label><label>DAC Referenz<select id=\"hwRatiometric\"><option value=\"0\">Absolut</option><option value=\"1\">Ratiometrisch</option></select></label><label class=\"check\"><input id=\"hwCap\" type=\"checkbox\"> DACCAP aktivieren</label><label>DAC Testcode<input id=\"hwTestCode\" type=\"number\" min=\"0\" max=\"16383\" value=\"1638\"></label></div><div class=\"gw-panel-actions\"><button id=\"hwOutRead\">Ausgang auslesen</button><button id=\"hwOutApply\">RAM übernehmen</button><button id=\"hwDAC\">DAC Testwert ausgeben</button><button id=\"hwDACStop\">DAC deaktivieren</button><button id=\"hwOutPrepare\">Nur Ausgang für EEPROM vorbereiten</button></div><p class=\"muted\">Nur mit passender externer Beschaltung und Last. Analogen Istwert extern messen. RAM-Test ist nicht der kompensierte DSP-Ausgang.</p></div><div class=\"gw-fields\"><label>Unterer Clamp (DAC Code)<input id=\"clow\" type=\"number\" min=\"0\" max=\"16383\" value=\"819\"></label><label>Oberer Clamp (DAC Code)<input id=\"chigh\" type=\"number\" min=\"0\" max=\"16383\" value=\"15564\"></label></div><div class=\"gw-alert\">Ausgangsart und DAC-Gain im RAM testbar. DAC-Grenzen werden im linearen Zielimage übernommen. Versorgung, Last und Diagnose mit TI-Vorgaben prüfen. Die Clamp-Werte werden nicht auf den Fit angewendet.</div></section>\n<section id=\"gwPage9\" class=\"gw-page\" data-page=\"8\" hidden><h2>EEPROM, Abschluss und Archiv</h2><div class=\"gw-alert\"><strong>Experimenteller EEPROM-Schreibpfad.</strong> Nur linearer Hardwareabgleich, mit vollständigem Backup, quantisierter Modellprüfung und expliziter Testchip-Freigabe. TC/NL-Festkommawerte bleiben gesperrt.</div><div class=\"gw-panel-actions\"><button id=\"hwBackup\">Original-EEPROM sichern (.bin)</button><button id=\"hwPrepare\">Lineares EEPROM vorbereiten</button><button id=\"hwProgram\" class=\"danger\" disabled>Testchip programmieren</button></div><label>Original-Backup zur Wiederherstellung (.bin)<input id=\"hwRestoreFile\" type=\"file\" accept=\".bin\"></label><button id=\"hwRestore\">Geschützte Wiederherstellung vorbereiten</button><pre id=\"hwDiff\">Noch kein Zielimage.</pre><p id=\"summary\"></p><div class=\"gw-panel-actions\"><button id=\"export\">JSON-Bericht</button><button id=\"csv\">Messwerte CSV</button><button id=\"print\">Kalibrierbericht / PDF</button></div><h3>Freigabecheckliste (offen)</h3><ul><li>OWI-Hardware und Chipidentifikation validieren</li><li>Original-EEPROM sichern; Adressen, CRC und reservierte Bits prüfen</li><li>Koeffizienten gegen TI-Rechner und reale DAC-Werte validieren</li><li>Schreiben mit expliziter Freigabe, Rücklesen und Kaltstart prüfen</li></ul></section>\n<section id=\"gwPage8\" class=\"gw-page\" data-page=\"10\" hidden><div class=\"gw-tile\"><h3>Diagnose und Fehlerreaktion</h3><p>Diagnose-Konfiguration aus EEPROM lesen, Änderungen vorbereiten und über den Testchip-Schreibpfad sichern. Fehlerreaktion real am Prüfplatz testen.</p><div class=\"gw-fields\"><label>Fehlerreaktion (Projektvorgabe)<select id=\"alarmReaction\"><option>Unverändert</option><option>Unterer Ausgang</option><option>Oberer Ausgang</option><option>Extern definierte Reaktion</option></select></label><label>Notiz zur Diagnose<input id=\"alarmNote\"></label></div><button id=\"alarmSave\">Plan speichern</button><div class=\"gw-fields\"><label class=\"check\"><input id=\"hwDiagEnable\" type=\"checkbox\"> Diagnose aktivieren</label><label>Fehler-DAC (0–16383)<input id=\"hwFault\" type=\"number\" value=\"3293\" min=\"0\" max=\"16383\"></label><label>AFEDIAG_MASK (Hex)<input id=\"hwDiagMask\" value=\"33\" maxlength=\"2\"></label></div><div class=\"gw-panel-actions\"><button id=\"hwAlarmRead\">EEPROM-Diagnose auslesen</button><button id=\"hwAlarmPrepare\">Nur Diagnose für EEPROM vorbereiten</button></div></div></section>\n<section id=\"tiTool11\" class=\"gw-page\" data-page=\"11\" hidden><div class=\"gw-columns\"><section class=\"gw-tile\"><h3>Brücke bei Referenztemperatur</h3><div class=\"gw-fields\"><label>Brückenspeisung (V)<input id=\"bridgeV\" type=\"number\" step=\"any\" value=\"5\"></label><label>Nullpunkt (mV)<input id=\"bridgeLo\" type=\"number\" step=\"any\"></label><label>Endwert (mV)<input id=\"bridgeHi\" type=\"number\" step=\"any\"></label><label>Referenztemperatur (°C)<input id=\"bridgeT0\" type=\"number\" value=\"25\"></label></div></section><section class=\"gw-tile\"><h3>Zweite Temperatur (optional)</h3><div class=\"gw-fields\"><label>Temperatur (°C)<input id=\"bridgeT1\" type=\"number\" step=\"any\"></label><label>Nullpunkt (mV)<input id=\"bridgeLo1\" type=\"number\" step=\"any\"></label><label>Endwert (mV)<input id=\"bridgeHi1\" type=\"number\" step=\"any\"></label></div></section></div><button id=\"bridgeCalc\" class=\"primary\">Brücke berechnen</button><div id=\"bridgeResult\" class=\"gw-summary\" aria-live=\"polite\">Externe differenzielle Brückenspannungen eingeben. Keine Rückrechnung aus ungeprüften EEPROM-Registern.</div></section>\n<section id=\"tiTool12\" class=\"gw-page\" data-page=\"12\" hidden><div class=\"gw-tile\"><h3>EEPROM-Viewer · Offline</h3><p>EEPROM aus dem Sensor lesen oder Binärabbild offline ansehen. Bei Sensorzugriff werden definierte Registerfelder dekodiert.</p><label>Binärdatei<input id=\"dumpFile\" type=\"file\" accept=\".bin,.dat,.rom\"></label><pre id=\"dumpView\">Keine Datei geladen.</pre><button id=\"dumpClear\">Ansicht leeren</button></div><div class=\"gw-alert\">OWI-Hardwarepfad experimentell. Seriennummer ist kundenspezifisch, keine unveränderliche Chip-UID. Keine sichere Identifikation eines neuen Chips allein anhand dieser Nummer.</div><div class=\"gw-panel-actions\"><button id=\"hwInspect\">EEPROM vom Sensor auslesen</button><button id=\"hwDumpBackup\">EEPROM .bin exportieren</button></div><label>Register suchen<input id=\"registerSearch\" placeholder=\"Adresse / Name\"></label><div class=\"ti-scroll\" style=\"max-height:400px\"><table><thead><tr><th>Adresse</th><th>Register</th><th>Hex</th><th>Schutz</th></tr></thead><tbody id=\"registerRows\"></tbody></table></div><pre id=\"hwDecoded\"></pre><button id=\"diagExport\">Diagnosebericht exportieren</button></section>\n<section id=\"tiTool13\" class=\"gw-page\" data-page=\"13\" hidden><div class=\"gw-tile\"><h3>Test / Logging · manuelle Erfassung</h3><div class=\"gw-fields gw-3\"><label>PADC<input id=\"logP\" type=\"number\"></label><label>TADC<input id=\"logT\" type=\"number\"></label><label>DAC Ist<input id=\"logD\" type=\"number\"></label><label>Referenzdruck<input id=\"logRef\" type=\"number\" step=\"any\"></label><label>Referenztemperatur<input id=\"logTemp\" type=\"number\" step=\"any\"></label><label>Notiz<input id=\"logNote\"></label></div><div class=\"gw-panel-actions\"><button id=\"hwLog\">SSC-Messung erfassen</button><button id=\"hwLogAuto\">Intervall-Logging starten</button><label>Intervall (ms)<input id=\"hwLogInterval\" type=\"number\" min=\"250\" max=\"10000\" value=\"1000\"></label><button id=\"logAdd\" class=\"primary\">Messwert erfassen</button><button id=\"logExport\">CSV exportieren</button><button id=\"logArchive\">Im Archiv speichern</button><button id=\"logClear\">Leeren</button></div><div class=\"ti-scroll\"><table><thead><tr><th>Zeit</th><th>PADC</th><th>TADC</th><th>DAC</th><th>Referenz</th><th>°C</th><th>Notiz</th></tr></thead><tbody id=\"logRows\"></tbody></table></div></div><p class=\"muted\">Manuelle und automatische OWI-ADC-Aufzeichnung im Konfigurationsmodus.</p></section>\n<section id=\"tiTool14\" class=\"gw-page\" data-page=\"14\" hidden><div class=\"gw-tile\"><h3>Lokales Archiv</h3><p>Berichte im Browser dieses Geräts speichern. Zur dauerhaften Sicherung zusätzlich JSON exportieren.</p><div class=\"gw-panel-actions\"><button id=\"archiveSave\" class=\"primary\">Aktuellen Bericht speichern</button><label>Bericht importieren<input id=\"archiveImport\" type=\"file\" accept=\".json\"></label></div><label>Suche<input id=\"archiveSearch\" placeholder=\"Sensor, Datum, Typ\"></label><div class=\"gw-panel-actions\"><button id=\"archiveFolder\">Archivordner auswählen</button><button id=\"archiveFolderExport\">Berichte in Ordner sichern</button></div><p id=\"archiveFolderStatus\">Kein Ordner gewählt (Browserarchiv aktiv).</p><div class=\"gw-fields\"><label>Vergleich A<select id=\"archiveA\"></select></label><label>Vergleich B<select id=\"archiveB\"></select></label></div><button id=\"archiveCompare\">Berichte vergleichen</button><pre id=\"archiveComparison\"></pre><div id=\"archiveList\"></div><pre id=\"archiveDetail\" hidden></pre></div></section>\n<section id=\"gwPage10\" class=\"gw-page\" data-page=\"15\" hidden><div class=\"gw-tile\"><h3>Abschluss</h3><p id=\"finishStatus\"></p><div class=\"gw-tile\"><h3>Kaltstart und reale Ausgangsprüfung</h3><p>Nach EEPROM-Programmierung in Execution-Modus wechseln, Versorgung physisch aus/ein, anschliessend EEPROM erneut lesen und vergleichen. Externe Ausgangsmessungen bei mindestens zwei Referenzen erfassen.</p><div class=\"gw-panel-actions\"><button id=\"coldExit\">Execution-Modus / trennen</button><button id=\"coldCompare\">Nach erneutem Verbinden EEPROM vergleichen</button></div><p id=\"coldStatus\">Noch keine Programmierung.</p><div class=\"gw-fields\"><label>Referenzdruck<input id=\"analogRef\" type=\"number\" step=\"any\"></label><label>Soll V / mA<input id=\"analogTarget\" type=\"number\" step=\"any\"></label><label>Ist V / mA<input id=\"analogActual\" type=\"number\" step=\"any\"></label><label>Toleranz (gleiche Einheit)<input id=\"analogTol\" type=\"number\" step=\"any\" value=\"0.01\"></label></div><button id=\"analogAdd\">Messung hinzufügen</button><button id=\"analogCheck\">Ausgang prüfen</button><button id=\"analogClear\">Messungen leeren</button><pre id=\"analogResult\"></pre></div><div class=\"gw-panel-actions\"><button id=\"finishSave\" class=\"primary\">Bericht archivieren</button><button id=\"finishExport\">JSON exportieren</button><button id=\"finishHome\">Zur Aufgabenauswahl</button></div></div></section><footer class=\"gw-footer\"><small id=\"footerHint\">Laborversion · Offline</small><div class=\"gw-actions\"><button id=\"back\">Zurück</button><button id=\"next\" class=\"primary\">Weiter</button></div></footer></div></div></div></div>";
document.documentElement.classList.add('guided-active');document.head.querySelector('link[href="./style.css"]')?.remove();for(const name of ['master-base.css','master-guided.css','master-interface.css','master-theme.css','pga300-master.css']){const link=document.createElement('link');link.rel='stylesheet';link.href='./'+name;document.head.append(link)}
const $=id=>document.getElementById(id),num=id=>$(id).valueAsNumber, val=id=>$(id).value, fmt=x=>Number.isFinite(x)?Number(x.toPrecision(8)).toString():'—';
const order=[0,2,3,4,5,9,6,7,10,8,15];
const meta={0:['Aufgabe','Was möchtest du machen?','Wähle dein Ziel. Danach werden nur die benötigten Schritte angezeigt.'],1:['Verbindung','Verbindung & Diagnose','Adapter und Erfassungsmodus festlegen.'],2:['Abgleich planen','Wie genau möchtest du abgleichen?','Druckpunkte und Temperaturstufen festlegen.'],3:['Sensor vorbereiten','Sensor und Referenzen definieren','Druckbereich, Temperatur und DAC-Zielwerte festlegen.'],4:['Frontend einstellen','AFE optimal einstellen','Externe AFE-Konfiguration dokumentieren.'],5:['Messpunkte','Jetzt die Referenzen messen','Referenzbedingungen einstellen und ADC-Werte aufnehmen.'],9:['Koeffizienten','Kalibrierung berechnen','Druck- und Temperaturmodell berechnen.'],6:['Modell verifizieren','Ergebnis unabhängig prüfen','Andere Messpunkte als für die Kalibrierung verwenden.'],7:['Ausgang','Ausgang und Skalierung','DAC-Zielwerte und Grenzen planen.'],10:['Alarme','Alarme & Fehler (optional)','Fehlerreaktionen dokumentieren.'],8:['EEPROM','Sicher im Sensor speichern','Experimenteller Testchip-Schreibpfad mit Backup und Rücklesung.'],15:['Fertig','Bericht abschliessen','Bericht speichern; Kaltstart und analoge Nachmessung kontrollieren.'],11:['Brücken-Rechner','Sensorbrücken-Rechner','Brückenmessungen in mV/V auswerten.'],12:['EEPROM / Diagnose','EEPROM / Diagnose','Externe Speicherabbilder ansehen.'],13:['Test / Logging','Test / Logging','Manuelle Messwerte zeitgestempelt erfassen.'],14:['Archiv','Archiv','Berichte und Messungen verwalten.']};
let task='calibration',classic=false,visited=new Set([0]);
let archiveDir=null,postWriteSerial=null,coldExited=false,q14=null,outFit=null,restoreBytes=null,registerBytes=null,postWriteImage=null,coldMatch=false,analogRows=[],analogResult=null,trend=[],logTimer=null,device=null,transport=null,afeApplied=null,hwSnapshot=null,prepared=null,backupSaved=false,programmed=false,hwBusy=false,pollTimer=null;const hwCaptured=new Set();
let page=0,points=[],fit=null,checked=null,checkRows=[],provenance=null,fitSpec=null;
const configIds=['pc','tc','po','to','thermalFit','min','max','unit','temps','dacLow','dacHigh','output','vdd','pg','tg','ts','samples','clow','chigh'];
const config=()=>Object.fromEntries(configIds.map(id=>[id,val(id)]));
const spec=()=>({min:num('min'),max:num('max'),pCount:Number(val('pc')),temperatures:val('temps').split(',').map(x=>x.trim()===''?NaN:Number(x)),dacLow:num('dacLow'),dacHigh:num('dacHigh'),thermalFit:val('thermalFit')});
function msg(s){$('notice').textContent=s;$('notice').hidden=!s}
function invalidate(){q14=null;$('q14Result').textContent='';$('q14Compare').textContent='';clearPrepared();fit=null;checked=null;fitSpec=null;$('fitResult').hidden=true;$('verification').textContent='';$('graph').replaceChildren();$('checks').querySelectorAll('tr').forEach(tr=>tr.cells[4].textContent='—');$('measure').querySelectorAll('tr').forEach(tr=>tr.cells[6].textContent='—')}
function reset(){hwCaptured.clear();for(const id of ['liveAdcS','liveAdcT','liveTempC','livePressure','liveDspS','liveLastRead'])$(id).textContent='—';points=[];checkRows=[];provenance=null;invalidate();renderPoints();renderChecks();$('afeConfirmed').checked=false}
function concept(){const p=+val('pc'),t=+val('tc'),po=+val('po'),to=+val('to');$('concept').textContent=(val('thermalFit')==='tk0'?3:p*t)+' Messpunkte · '+(val('thermalFit')==='tk0'?3:(po+1)*(to+1))+' freie Modellkoeffizienten';if(po>=p||to>=t) $('concept').textContent+=' · Ordnung zu hoch für gewählte Matrix.'}
function validSpec(){const s=spec();if(s.temperatures.length!==+val('tc')||+val('po')>=s.pCount||+val('to')>=s.temperatures.length)throw Error('Messkonzept und Temperaturstufen stimmen nicht überein.');return s}
function nav(n){if(!meta[n])return;page=n;visited.add(n);document.querySelectorAll('[data-page]').forEach(s=>s.hidden=+s.dataset.page!==page);$('gwTitle').textContent=meta[n][1];$('gwDesc').textContent=meta[n][2];const ix=order.indexOf(n);$('kicker').textContent=ix>=0?'Schritt '+(ix+1)+' / '+order.length:'Werkzeug';$('progress').style.width=(ix>=0?100*ix/(order.length-1):0)+'%';$('back').disabled=n===0;$('next').hidden=n===0||n===15||ix<0||(task!=='calibration'&&n!==1);[...$('steps').children].forEach(b=>{const p=+b.dataset.pageTarget;b.classList.toggle('is-active',p===n);b.classList.toggle('is-done',p!==n&&visited.has(p));b.setAttribute('aria-current',p===n?'step':'false')});if(n===7||n===3){const host=$(n===7?'outputFields':'sensorFields');for(const id of ['dacLow','dacHigh','output','vdd'])host.append($(id).closest('label'));}if(n===7)$('outSummary').textContent=val('output')+' · '+val('dacLow')+' bis '+val('dacHigh')+' DAC Codes · '+val('vdd')+' V (Plan)';if(n===8||n===15){const summary=(fit?'Modell berechnet. ':'Keine Modellberechnung. ')+(checked?.pass?'Modellprüfung innerhalb Toleranz. ':'Keine erfolgreiche Modellprüfung. ')+(postWriteImage?(coldMatch?'EEPROM nach bestätigtem Kaltstart identisch. ':'EEPROM rückgelesen; Kaltstart offen. ')+(analogResult?.pass?'Externe Messung bestanden.':'Externe Messung offen oder nicht bestanden.'):'Keine Produktionsfreigabe.');$('summary').textContent=summary;$('finishStatus').textContent=summary;}if(n===14)renderArchive();if(n===13)renderLog();msg('')}
function next(){try{if(page===1){if(val('mode')==='hardware'&&!device?.active)throw Error('Zuerst OWI verbinden.');nav(2);return}if(page===2){concept();if(+val('po')>=+val('pc')||+val('to')>=+val('tc'))throw Error('Polynomordnung passt nicht zur Messmatrix.');}if(page===3)matrix(validSpec());if(page===4){if(val('mode')==='hardware'&&!afeApplied)throw Error('AFE zuerst im RAM einstellen und rücklesen.');if(!$('afeConfirmed').checked)throw Error('AFE zuerst bestätigen.');if(!points.length)make()}if(page===5){if(provenance==='hardware'&&hwCaptured.size!==points.length)throw Error('Alle Referenzpunkte vom SSC erfassen.');if(!points.length||points.some(x=>!Number.isInteger(x.p)||!Number.isInteger(x.t)))throw Error('Alle Messpunkte erfassen.');}if(page===9&&!fit)throw Error('Zuerst Koeffizienten berechnen.');if(page===6&&!checked?.pass)throw Error('Erfolgreiche Modellprüfung erforderlich.');if(page===7&&!(num('clow')>=0&&num('clow')<=num('dacLow')&&num('chigh')>=num('dacHigh')&&num('chigh')<=16383))throw Error('Clamp-Grenzen müssen die DAC-Zielwerte einschliessen.');const i=order.indexOf(page);if(i>=0&&i<order.length-1)nav(order[i+1])}catch(e){msg(e.message)}}
function field(v,callback,aria){const e=document.createElement('input');e.type='number';e.step='any';e.value=v??'';e.setAttribute('aria-label',aria);e.addEventListener('input',()=>callback(e.valueAsNumber));return e}
function cell(tr,v){const td=tr.insertCell();if(v instanceof Node)td.append(v);else td.textContent=v;return td}
function renderPoints(){$('measure').replaceChildren();points.forEach((p,i)=>{const tr=$('measure').insertRow();[i+1,fmt(p.pressure),fmt(p.temperature),fmt(p.target)].forEach(v=>cell(tr,v));for(const key of ['p','t'])cell(tr,field(p[key],v=>{p[key]=v;hwCaptured.delete(p.id);invalidate();capture()},key+' Punkt '+(i+1)));cell(tr,'—')});capture()}
function capture(){const i=points.findIndex(p=>!Number.isInteger(p.p)||!Number.isInteger(p.t));$('capture').textContent=!points.length?'Noch keine Messmatrix.':i<0?'Alle '+points.length+' Punkte erfasst.':'Nächster Punkt '+(i+1)+' / '+points.length+': '+fmt(points[i].pressure)+' '+val('unit')+' bei '+points[i].temperature+' °C'}
function make(){if(val('mode')==='hardware'&&(!device?.active||!afeApplied))throw Error('Hardware und rückgelesene AFE erforderlich.');if(!$('afeConfirmed').checked)throw Error('AFE zuerst bestätigen.');points=matrix(validSpec());hwCaptured.clear();checkRows=[];provenance=val('mode')==='hardware'?'hardware':val('mode')==='demo'?'synthetic':'manual';invalidate();renderPoints();renderChecks()}
function demo(){if(device?.active)throw Error('Zuerst Hardware trennen.');if(!$('afeConfirmed').checked)throw Error('AFE zuerst bestätigen.');$('mode').value='demo';make();provenance='synthetic';const s=spec();for(const x of points){const frac=(x.pressure-s.min)/(s.max-s.min);x.p=Math.round(2000+20000*frac+(x.temperature-25)*8);x.t=Math.round(7500+25*(x.temperature-25))}renderPoints();msg('Synthetische Werte – keine Sensormessung.')}
function calc(){if(provenance==='hardware'&&(!device?.active||hwCaptured.size!==points.length))throw Error('Alle Referenzpunkte direkt vom SSC erfassen.');if(!points.length||!$('afeConfirmed').checked)throw Error('Messmatrix und AFE-Bestätigung fehlen.');invalidate();fit=solve(points,+val('po'),+val('to'),val('thermalFit'));fitSpec=config();$('fitResult').hidden=false;$('fitMetrics').textContent='Max. Fehler: '+fmt(fit.maxError)+' DAC · RMS: '+fmt(fit.rms)+' DAC · '+(fit.thermalFit==='tk0'?3:fit.coefficients.length)+' freie Koeffizienten';$('coeff').replaceChildren();fit.coefficients.forEach((v,k)=>{const tr=$('coeff').insertRow();cell(tr,'hgnm'[Math.floor(k/(fit.to+1))]+(k%(fit.to+1)));cell(tr,fmt(v))});const l=linearCandidate(fit);$('linear').textContent=l?'Lineares TI-Beispielverfahren (digitale Skalierung = Identität):\nh0 = '+l.h0+' · g0 = '+l.g0+' · '+(l.representable?'signed-16-bit darstellbar':'ausserhalb signed-16-bit')+'\nNicht zum Programmieren freigegeben.':'';points.forEach((p,i)=>$('measure').rows[i].cells[6].textContent=fmt(fit.residuals[i]));q14=q14Candidate(fit,points);$('q14Result').textContent=JSON.stringify(q14,null,2);msg('Modell berechnet. Unabhängige Prüfpunkte erforderlich.')}
function renderChecks(){$('checks').replaceChildren();checkRows.forEach((x,i)=>{const tr=$('checks').insertRow();for(const key of ['p','t','target','actual'])cell(tr,field(x[key],v=>{x[key]=v;if(key==='p'||key==='t')x.hardware=false;clearChecks()},key+' Prüfpunk '+(i+1)));cell(tr,'—');const rm=document.createElement('button');rm.textContent='Entfernen';rm.onclick=()=>{checkRows.splice(i,1);clearChecks();renderChecks()};cell(tr,rm)})}
function clearChecks(){clearPrepared();checked=null;$('verification').textContent='';$('graph').replaceChildren();[...$('checks').rows].forEach(tr=>tr.cells[4].textContent='—')}
function check(){clearChecks();if(!fit)throw Error('Modell fehlt.');checked=verify(fit,points,checkRows,num('tol'));let actualPass=true,actualCount=0;checked.checks.forEach((x,i)=>{if(Number.isFinite(x.actual)){actualCount++;if(x.actual<0||x.actual>16383||Math.abs(x.actual-x.target)>checked.tolerance)actualPass=false}$('checks').rows[i].cells[4].textContent=(x.pass?'OK':'FEHLER')+' · Modell '+fmt(x.error)+(Number.isFinite(x.actual)?' · Ist '+fmt(x.actual-x.target):'')});checked.actualCount=actualCount;checked.actualPass=actualCount?actualPass:null;checked.pass=checked.pass&&actualPass;$('verification').textContent=(checked.pass?'Modellprüfung bestanden':'Prüfung nicht bestanden')+' · '+actualCount+' Ist-Messwerte · keine Chipfreigabe';draw()}
function draw(){const svg=$('graph'),ns='http://www.w3.org/2000/svg';svg.replaceChildren();const el=(tag,a)=>{const e=document.createElementNS(ns,tag);Object.entries(a).forEach(([k,v])=>e.setAttribute(k,v));svg.append(e);return e};const lim=Math.max(checked.tolerance,...checked.checks.map(x=>Math.abs(x.error)))*1.15;const y=x=>105-85*x/lim;for(const v of [-checked.tolerance,0,checked.tolerance]){el('line',{x1:40,x2:580,y1:y(v),y2:y(v),stroke:v?'#b87824':'#778899','stroke-dasharray':v?'5 4':'0'});el('text',{x:2,y:y(v)+4,fill:'currentColor','font-size':11}).textContent=fmt(v)}checked.checks.forEach((x,i)=>el('circle',{cx:40+540*(i+.5)/checked.checks.length,cy:y(x.error),r:5,fill:x.pass?'#16866a':'#b33844'}))}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function report(){return {schema:'pga300-offline-v1',timestamp:new Date().toISOString(),sensor:val('sensor'),adapter:val('adapter'),mode:provenance??val('mode'),configuration:config(),fitConfiguration:fitSpec,points,fit,verificationRows:checkRows,verification:checked,hardwareValidated:false,hardwareSession:device?.active?'configuration-mode':'disconnected',eepromProgrammed:!!postWriteImage,coldStartReadback:coldMatch,analogVerification:analogResult,tcCandidate:q14,programmingAllowed:false}}
function csv(){const rows=[['type','pressure','temperature','pADC','tADC','targetDAC','actualDAC','modelError'],...points.map((p,i)=>['calibration',p.pressure,p.temperature,p.p,p.t,p.target,'',fit?.residuals[i]]),...checkRows.map((p,i)=>['verification','','',p.p,p.t,p.target,p.actual,checked?.checks[i]?.error])];download('pga300-messwerte.csv',rows.map(r=>r.map(v=>Number.isFinite(v)||typeof v==='string'?v:'').join(';')).join('\n'),'text/csv')}
function guarded(fn){return ()=>{try{fn()}catch(e){msg(e.message)}}}
