$('tol').oninput=clearChecks;$('make').onclick=guarded(make);$('demo').onclick=guarded(demo);$('calculate').onclick=guarded(()=>{nav(9);calc()});$('recalculate').onclick=guarded(calc);$('addCheck').onclick=()=>{checkRows.push({p:null,t:null,target:null,actual:null});clearChecks();renderChecks()};$('runCheck').onclick=guarded(check);$('demoCheck').onclick=guarded(()=>{if(provenance!=='synthetic'||!fit)throw Error('Nur für einen berechneten synthetischen Datensatz.');const s=spec(),temperature=s.temperatures[0]+(s.temperatures.at(-1)-s.temperatures[0])*0.37,frac=0.37;checkRows.push({p:Math.round(2000+20000*frac+(temperature-25)*8),t:Math.round(7500+25*(temperature-25)),target:s.dacLow+(s.dacHigh-s.dacLow)*frac,actual:null});clearChecks();renderChecks();msg('Synthetischer Prüfpunkt, keine reale Messung.');});$('next').onclick=next;$('back').onclick=()=>{const i=order.indexOf(page);if(page===2&&task==='calibration')nav(1);else if(task!=='calibration'||i<1)goHome();else nav(order[i-1])};
