$('loadConfig').onchange=async()=>{try{const file=$('loadConfig').files[0];if(!file)return;if(file.size>100000)throw Error('Config zu gross.');const x=JSON.parse(await file.text());if(x.schema!=='pga300-config-v1'||!x.config||configIds.some(id=>typeof x.config[id]!=='string'))throw Error('Ungültige Config.');const old=config();try{for(const id of configIds)$(id).value=x.config[id];matrix(validSpec());if(configIds.some(id=>val(id)!==x.config[id]))throw Error('Ungültiger Feldwert.')}catch(e){for(const id of configIds)$(id).value=old[id];throw e}reset();concept();msg('Config übernommen. Neue Messung erforderlich.')}catch(e){msg(e.message)}finally{$('loadConfig').value=''}};
