let log=[],dumpMeta=null,bridgeData=null,alarmPlan=null;
const storeKey='ti-pga300-archive-v2';
function archiveRead(){try{const x=JSON.parse(localStorage.getItem(storeKey)||'[]');return Array.isArray(x)?x:[]}catch{return []}}
function archiveWrite(rows){localStorage.setItem(storeKey,JSON.stringify(rows))}
function archiveAdd(type,data){const rows=archiveRead();rows.unshift({id:Date.now()+'-'+Math.random().toString(36).slice(2),type,date:new Date().toISOString(),sensor:val('sensor'),data});archiveWrite(rows.slice(0,100));msg('Lokal im Browserarchiv gespeichert.')}
function fullReport(){return {...report(),bridge:bridgeData,alarmPlan,log,diagnostics:dumpMeta}}
function renderArchive(){refreshArchiveSelectors();const q=val('archiveSearch').toLowerCase();$('archiveList').replaceChildren();$('archiveDetail').hidden=true;const rows=archiveRead().filter(x=>[x.type,x.date,x.sensor].join(' ').toLowerCase().includes(q));if(!rows.length)$('archiveList').textContent='Keine Berichte vorhanden.';for(const x of rows){const row=document.createElement('div');row.className='ti-archive-row';const label=document.createElement('strong');label.textContent=x.type+' · '+x.date+' · '+(x.sensor||'Ohne Sensor-ID');row.append(label);for(const [title,action] of [['Ansehen',()=>{$('archiveDetail').hidden=false;$('archiveDetail').textContent=JSON.stringify(x.data,null,2)}],['JSON',()=>download('pga300-archiv.json',JSON.stringify(x.data,null,2),'application/json')],['Löschen',()=>{if(confirm('Diesen lokalen Bericht löschen?')){archiveWrite(archiveRead().filter(y=>y.id!==x.id));renderArchive()}}]]){const b=document.createElement('button');b.textContent=title;b.onclick=guarded(action);row.append(b)}$('archiveList').append(row)}}
function renderLog(){$('logRows').replaceChildren();for(const x of log){const tr=$('logRows').insertRow();for(const key of ['time','p','t','dac','reference','temperature','note'])cell(tr,x[key]??'')}}
function optional(id){const v=num(id);return Number.isFinite(v)?v:null}
function csvCell(x){let s=String(x??'');if(typeof x==='string'&&/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
function logCsv(){const rows=[['time','PADC','TADC','DAC','reference','temperature','note'],...log.map(x=>[x.time,x.p,x.t,x.dac,x.reference,x.temperature,x.note])];download('pga300-logging.csv',rows.map(row=>row.map(csvCell).join(';')).join('\n'),'text/csv')}
function updateLive(p){if(!p)return;$('liveAdcS').textContent=fmt(p.p);$('liveAdcT').textContent=fmt(p.t);$('liveTempC').textContent=fmt(p.temperature);$('livePressure').textContent=fmt(p.pressure??p.reference);$('livePressureUnit').textContent=val('unit')+' · Referenz';$('liveDspS').textContent=fit&&Number.isInteger(p.p)&&Number.isInteger(p.t)?fmt(fit.coefficients.reduce((s,c,k)=>s+c*((p.p-fit.ps.center)/fit.ps.span)**Math.floor(k/(fit.to+1))*((p.t-fit.ts.center)/fit.ts.span)**(k%(fit.to+1)),0)):'—';$('liveLastRead').textContent='Manuell / Offline'}
function goHome(){if(hwBusy){msg('Sensoroperation läuft.');return}stopLive();if(classic)setClassic(false);task='calibration';nav(0)}
