$('settingsClose').onclick=()=>{$('settingsPanel').hidden=true;$('settingsOpen').setAttribute('aria-expanded','false')};
function setClassic(on){classic=on;document.documentElement.classList.toggle('ti-classic',on);$('classicSetting').checked=on;$('guidedLaunchTop').textContent=on?'◇ Geführt':'▤ Klassisch';$('guidedLaunchTop').setAttribute('aria-pressed',String(!on));try{localStorage.setItem('ti-pga300-view',on?'classic':'guided')}catch{}}
$('guidedLaunchTop').onclick=()=>setClassic(!classic);$('classicSetting').onchange=()=>setClassic($('classicSetting').checked);
