$('bridgeCalc').onclick=guarded(()=>{const v=num('bridgeV'),lo=num('bridgeLo'),hi=num('bridgeHi'),t0=num('bridgeT0');if(![v,lo,hi,t0].every(Number.isFinite)||v<=0||hi===lo)throw Error('Gültige Brückenspannungen, Speisung und Temperatur erforderlich.');const span=(hi-lo)/v;bridgeData={excitationV:v,zero:lo/v,span,temperature:t0};let out='Nullpunkt: '+fmt(lo/v)+' mV/V · Spanne: '+fmt(span)+' mV/V';const second=['bridgeT1','bridgeLo1','bridgeHi1'].map(num);if(second.some(Number.isFinite)){if(!second.every(Number.isFinite)||second[0]===t0)throw Error('Zweite Temperatur und beide Brückenwerte vollständig angeben.');const [t,l,h]=second,dt=t-t0;bridgeData.tk0=(l-lo)/v/dt;bridgeData.tke=((h-l)/v-span)/span/dt*100;out+=' · TK0: '+fmt(bridgeData.tk0)+' mV/V/K · TKE: '+fmt(bridgeData.tke)+' %/K (konstante Speisung)'}$('bridgeResult').textContent=out});
$('dumpFile').onchange=async()=>{try{const file=$('dumpFile').files[0];if(!file)return;if(file.size>65536)throw Error('Datei zu gross (max. 64 KiB).');const bytes=new Uint8Array(await file.arrayBuffer()),lines=[];for(let i=0;i<bytes.length;i+=16)lines.push(i.toString(16).padStart(4,'0')+'  '+Array.from(bytes.slice(i,i+16),x=>x.toString(16).padStart(2,'0')).join(' '));dumpMeta={filename:file.name,bytes:bytes.length,validated:false};$('dumpView').textContent=lines.join('\n')||'Leere Datei.'}catch(e){msg(e.message)}};
$('dumpClear').onclick=()=>{dumpMeta=null;$('dumpView').textContent='Keine Datei geladen.';$('dumpFile').value=''};
