$('logAdd').onclick=guarded(()=>{const p=num('logP'),t=num('logT'),dac=optional('logD');if(![p,t].every(x=>Number.isInteger(x)&&x>=-32768&&x<=32767)||dac!==null&&(!Number.isInteger(dac)||dac<0||dac>16383))throw Error('Gültige signed-16-bit ADC-Codes und optional 14-bit DAC eingeben.');const row={time:new Date().toISOString(),p,t,dac,reference:optional('logRef'),temperature:optional('logTemp'),note:val('logNote')};log.push(row);renderLog();updateLive(row)});
$('logExport').onclick=logCsv;$('logArchive').onclick=guarded(()=>{if(!log.length)throw Error('Keine Messwerte.');archiveAdd('Logging',{schema:'pga300-log-v1',log});});$('logClear').onclick=()=>{if(confirm('Erfasste Log-Daten leeren?')){log=[];renderLog()}};
