$('archiveImport').onchange=async()=>{try{const f=$('archiveImport').files[0];if(!f)return;if(f.size>2000000)throw Error('Datei zu gross.');const x=JSON.parse(await f.text());if(!['pga300-offline-v1','pga300-log-v1'].includes(x?.schema))throw Error('Kein unterstützter PGA300-Bericht.');archiveAdd('Import',x);renderArchive()}catch(e){msg(e.message)}finally{$('archiveImport').value=''}};
