function clearPrepared(){prepared=null;const btn=$('hwProgram');if(btn)btn.disabled=true;if($('hwDiff'))$('hwDiff').textContent='Noch kein Zielimage.'}
function requireDevice(){if(!device?.active||transport?.closed)throw Error('Zuerst USB / OWI verbinden.');return device}
function stopLive(){if(logTimer){clearInterval(logTimer);logTimer=null;$('hwLogAuto').textContent='Intervall-Logging starten'}if(pollTimer){clearInterval(pollTimer);pollTimer=null}$('hwLive').textContent='Live starten'}
function stateHardware(text){$('hwState').textContent=text;$('status').textContent=text;const badge=document.querySelector('.gw-chipstatus');badge.textContent=text;badge.classList.toggle('is-offline',!device?.active)}
async function busy(fn){if(hwBusy){msg('Sensorabfrage läuft. Live stoppen und nochmals versuchen.');return;}hwBusy=true;stopLive();const controls=[...document.querySelectorAll('button,input,select')],states=controls.map(x=>x.disabled);controls.forEach(x=>x.disabled=true);try{await fn()}catch(e){msg(e.message);if(transport?.closed){stateHardware('USB-Fehler – neu verbinden');if(device)device.active=false;hwSnapshot=null;backupSaved=false;afeApplied=null;$('hwWriteGate').checked=false;clearPrepared()}}finally{controls.forEach((x,i)=>x.disabled=states[i]);$('hwProgram').disabled=!prepared;hwBusy=false}}
function bind(id,fn){$(id).onclick=()=>void busy(fn)}
function showSample(x){trend.push({p:x.p,t:x.t});if(trend.length>120)trend.shift();renderTrend();updateLive(x);$('liveLastRead').textContent=new Date().toLocaleTimeString('de-CH');$('liveState').textContent='OWI · Konfigurationsmodus';$('hwADC').textContent='PADC '+x.p+' · TADC '+x.t+' · Min/Max '+x.min+' / '+x.max+' · AFEDIAG 0x'+hex(x.diag)+' '+decodeDiag(x.diag).join(', ')}
function showEEPROM(x){registerBytes=x.bytes.slice();renderRegisters();hwSnapshot=x;backupSaved=false;clearPrepared();$('hwDecoded').textContent=JSON.stringify({...x.decoded,chipCRC:x.chipCRC},null,2);const bytes=x.bytes;let lines=[];for(let i=0;i<128;i+=8)lines.push(hex(i)+'  '+Array.from(bytes.slice(i,i+8),hex).join(' '));$('dumpView').textContent=lines.join('\n');dumpMeta={filename:'PGA300 hardware',bytes:128,validated:x.chipCRC.good,decoded:x.decoded};msg('128 EEPROM-Bytes gelesen · CRC '+(x.chipCRC.good?'OK':'FEHLER')+' · Seriennummer '+x.decoded.serial)}
function loadAFE(a){$('hwPG').value=a.pGain&31;$('hwTG').value=a.tGain&3;$('hwInv').checked=!!(a.pGain&128);$('hwTInv').checked=!!(a.tGain&128);$('hwBridge').value=Math.min(2,(a.bridge>>1)&3);$('hwTemp').value=(a.temp&15)===3?'3':'0'}
bind('hwConnect',async()=>{if(device?.active)throw Error('Sensor bereits verbunden.');hwSnapshot=null;backupSaved=false;afeApplied=null;clearPrepared();if(!confirm('Nur an einem entbehrlichen Testchip mit geprüftem OWI-Frontend fortfahren. Der Analogausgang wird im Konfigurationsmodus unterbrochen.'))return;if(transport){try{await transport.close()}catch{}transport=null}$('hwWriteGate').checked=false;const selected=val('adapter');transport=selected==='evm'?await EvmBridge.open():await SerialBridge.open();device=new PGA300(transport);try{const info=await identifyAdapter(transport,selected);const x=await device.connect();connectedAdapter=selected;$('mode').value='hardware';reset();afeApplied=null;programmed=false;showEEPROM(x);loadAFE(await device.readAFE());stateHardware(info+' · OWI verbunden (experimentell)')}catch(e){try{await device.exit()}catch{}try{await transport.close()}catch{}device=null;transport=null;stateHardware('Verbindung fehlgeschlagen – Sensor ggf. neu einschalten');throw e}});
bind('hwDisconnect',async()=>{try{if(device?.active){await device.exit();if(postWriteImage)coldExited=true}}finally{if(transport)await transport.close().catch(()=>{});device=null;transport=null;connectedAdapter=null;$('hwWriteGate').checked=false;afeApplied=null;hwSnapshot=null;backupSaved=false;clearPrepared();$('mode').value='manual';reset();stateHardware('Nicht verbunden');$('liveState').textContent='Keine Live-Messung';msg('Execution-Befehl gesendet; Kaltstart am Prüfplatz kontrollieren.')}});
for(const id of ['hwRead','hwInspect'])bind(id,async()=>showEEPROM(await requireDevice().readEEPROM()));
for(const id of ['hwBackup','hwDumpBackup'])bind(id,async()=>{requireDevice();if(!hwSnapshot)throw Error('EEPROM zuerst auslesen.');download('PGA300-'+hwSnapshot.decoded.serial+'-original.bin',hwSnapshot.bytes,'application/octet-stream');backupSaved=true;msg('Backup-Download gestartet. Datei vor Programmierung separat kontrollieren.')});
bind('hwAFERead',async()=>{loadAFE(await requireDevice().readAFE());msg('AFE-Register ausgelesen.')});
bind('hwAFEApply',async()=>{const dev=requireDevice();if(!confirm('Temporäre AFE-Register ändern? Messpunkte werden verworfen.'))return;reset();afeApplied=null;const pGain=+val('hwPG')|($('hwInv').checked?128:0),tGain=+val('hwTG')|($('hwTInv').checked?128:0),bridge=(+val('hwBridge')<<1)|1,temp=0x40|+val('hwTemp');afeApplied=await dev.setAFE({pGain,tGain,bridge,temp,test:+val('hwTemp')===0?8:0});$('pg').value=PGA_GAINS[pGain&31];$('tg').value=TGAINS[tGain&3];$('ts').value=+val('hwTemp')===3?'Intern':'Extern';$('afeConfirmed').checked=true;msg('AFE im Konfigurationsmodus geschrieben und rückgelesen.')});
bind('hwSample',async()=>showSample(await requireDevice().sample(Math.min(100,Math.max(1,Math.round(num('samples')||1))))));
$('hwLive').onclick=()=>{if(pollTimer){stopLive();return}if(!device?.active){msg('Zuerst USB / OWI verbinden.');return}stopLive();$('hwLive').textContent='Live stoppen';let reading=false;pollTimer=setInterval(async()=>{if(reading||hwBusy)return;reading=true;hwBusy=true;try{showSample(await requireDevice().sample(1))}catch(e){stopLive();msg(e.message);if(transport?.closed){device.active=false;stateHardware('USB-Fehler – neu verbinden')}}finally{reading=false;hwBusy=false}},250)};
bind('hwCapture',async()=>{requireDevice();if(!afeApplied||!$('afeConfirmed').checked||provenance!=='hardware')throw Error('Hardwaremodus, AFE-Bestätigung und neue Messmatrix erforderlich.');const p=points.find(x=>!hwCaptured.has(x.id));if(!p)throw Error('Alle Hardwarepunkte erfasst. Für einen neuen Abgleich Matrix zurücksetzen.');if(!confirm('Referenz '+fmt(p.pressure)+' '+val('unit')+' bei '+p.temperature+' °C stabil?'))return;const x=await device.sample(Math.min(100,Math.max(1,Math.round(num('samples')||1))));if(x.min<=-32760||x.max>=32760)throw Error('ADC nahe Sättigung. AFE prüfen.');p.p=x.p;p.t=x.t;hwCaptured.add(p.id);invalidate();renderPoints();showSample({...x,pressure:p.pressure,temperature:p.temperature});msg('Hardwarepunkt '+p.id+' erfasst.')});
bind('hwVerifyCapture',async()=>{const x=await requireDevice().sample(1);const row={p:x.p,t:x.t,target:null,actual:null,hardware:true};checkRows.push(row);clearChecks();renderChecks();showSample(x);msg('ADC-Prüfpunkt erfasst. Referenz-DAC-Soll ergänzen. Istwert nur aus externer Ausgangsmessung.')});
bind('hwLog',async()=>{const x=await requireDevice().sample(1);log.push({time:new Date().toISOString(),p:x.p,t:x.t,dac:null,reference:optional('logRef'),temperature:optional('logTemp'),note:val('logNote')+' [OWI]'});renderLog();showSample(x)});
bind('hwPrepare',async()=>{assertWriteGate();if(requireDevice().writeFault)throw Error('Schreibpfad nach Fehler gesperrt.');if(!hwSnapshot||!backupSaved)throw Error('Original-EEPROM auslesen und Backup sichern.');if(!afeApplied||provenance!=='hardware'||hwCaptured.size!==points.length||!points.length||!fit||!checked?.pass||!checkRows.some(x=>x.hardware))throw Error('Vollständige Hardwaremessung und unabhängige Hardware-ADC-Modellprüfung nötig.');const actualAFE=await device.readAFE();for(const k of ['pGain','tGain','bridge','temp','test'])if(actualAFE[k]!==afeApplied[k])throw Error('AFE seit Messung verändert.');const candidate=linearCandidate(fit);if(!candidate?.representable)throw Error('Nur linearer Spezialfall ohne Temperaturkompensation ist zur experimentellen Kodierung implementiert.');const limit=num('tol');for(const x of [...points,...checkRows])if(Math.abs(4*candidate.h0+candidate.g0*x.p/16384-x.target)>limit)throw Error('Quantisierte lineare Kennlinie überschreitet Toleranz.');const original=hwSnapshot.bytes.slice();let desired=prepareLinear(original,candidate,afeApplied,{low:num('dacLow'),high:num('dacHigh'),clow:num('clow'),chigh:num('chigh')});if(original.every((x,i)=>x===desired[i]))throw Error('Keine Änderungen nötig.');prepared={original,desired};$('hwDiff').textContent=Array.from(desired,(v,i)=>original[i]===v?null:'0x'+hex(i)+'  '+hex(original[i])+' → '+hex(v)).filter(Boolean).join('\n');msg('Zielimage vorbereitet. CRC und reservierte Bits werden vor Programmierung nochmals geprüft.');});
bind('hwProgram',async()=>{assertWriteGate();if(!prepared||!backupSaved||!hwSnapshot||device?.writeFault)throw Error('Zielimage fehlt oder Schreibpfad gesperrt.');const a=prepared;clearPrepared();const phrase=prompt('Nur entbehrlicher Testchip! Backup gespeichert, Versorgung stabil, Sensor am Prüfplatz. Zum Schreiben exakt eingeben: PGA300 TESTCHIP PROGRAMMIEREN');if(phrase!=='PGA300 TESTCHIP PROGRAMMIEREN')return;let result;try{device.testWrites=true;result=await requireDevice().programImage(a.original,a.desired,phrase,msg)}catch(e){hwSnapshot=null;backupSaved=false;afeApplied=null;programmed=false;throw e}programmed=true;postWriteImage=result.bytes.slice();postWriteSerial=result.decoded.serial;coldExited=false;coldMatch=false;analogRows=[];analogResult=null;$('coldStatus').textContent='EEPROM programmiert. Kaltstart ausstehend.';showEEPROM(result);msg('EEPROM vollständig rückgelesen, CRC OK. Execution-Modus / Kaltstart und unabhängige Analogprüfung erforderlich. Keine Produktionsfreigabe.')});
