window.addEventListener('beforeunload',e=>{if(device?.active||hwBusy){e.preventDefault();e.returnValue=''}});

function showOut(a){$('hwOutStage').value=a.output&15;$('hwCap').checked=!!(a.output&16);$('hwRatiometric').value=a.dacConfig&1}
const outOptions=()=>({stage:+val('hwOutStage')|($('hwCap').checked?16:0),ratiometric:+val('hwRatiometric')});
bind('hwOutRead',async()=>{showOut(await requireDevice().readAFE());msg('Ausgangsregister gelesen.')});
bind('hwOutApply',async()=>{if(!confirm('Passende Ausgangsbeschaltung und Last überprüft? RAM-Ausgang ändern?'))return;const a=await requireDevice().setOutput(outOptions());showOut(a);clearPrepared();msg('Ausgangsregister rückgelesen; DAC bleibt deaktiviert.')});
bind('hwDAC',async()=>{if(!confirm('Testcode wird am Analogausgang wirksam. Last und Beschaltung geprüft?'))return;const v=await requireDevice().testDAC(num('hwTestCode'));clearPrepared();msg('DAC-Testregister '+v+' rückgelesen. Analogwert extern messen.')});
bind('hwDACStop',async()=>{await requireDevice().stopDAC();msg('DAC-Test deaktiviert.')});
bind('hwLowCapture',async()=>{const x=await requireDevice().sample(4);$('hwLow').value=x.p;showSample(x)});
bind('hwHighCapture',async()=>{const x=await requireDevice().sample(4);$('hwHigh').value=x.p;showSample(x)});
bind('hwGainRecommend',async()=>{const a=await requireDevice().readAFE(),v=recommendGain(num('hwLow'),num('hwHigh'),a.pGain&31);$('hwPG').value=v.code;$('hwInv').checked=Boolean(a.pGain&128)!==v.invert;$('hwGainAdvice').textContent='Vorschlag '+v.gain+' V/V · erwarteter Spitzenwert '+Math.round(v.predictedPeak)+' Digits. Übernehmen und beide Endpunkte erneut prüfen.';clearPrepared()});
function prepareOnly(options,label){assertWriteGate();if(requireDevice().writeFault)throw Error('Schreibpfad nach Fehler gesperrt.');if(!hwSnapshot||!backupSaved)throw Error('EEPROM zuerst auslesen und Originaldatei sichern.');const original=hwSnapshot.bytes.slice(),desired=prepareSettings(original,options);if(original.every((x,i)=>x===desired[i]))throw Error('Keine Änderungen nötig.');prepared={original,desired};nav(8);$('hwDiff').textContent=Array.from(desired,(v,i)=>original[i]===v?null:'0x'+hex(i)+'  '+hex(original[i])+' → '+hex(v)).filter(Boolean).join('\n');msg(label+' vorbereitet; nur explizit am Testchip programmieren.')}
bind('hwOutPrepare',async()=>{const opts=outOptions(),a=await requireDevice().readAFE();if((a.output&31)!==opts.stage||(a.dacConfig&1)!==opts.ratiometric)throw Error('Ausgang zuerst im RAM einstellen und prüfen.');if(!confirm('Ausgang anhand externer Messung geprüft?'))return;prepareOnly({...opts,normalLow:num('dacLow'),normalHigh:num('dacHigh'),lowClamp:num('clow'),highClamp:num('chigh')},'Nur Ausgang')});
bind('hwAlarmRead',async()=>{requireDevice();if(!hwSnapshot)throw Error('EEPROM auslesen.');const a=hwSnapshot.bytes;$('hwDiagEnable').checked=!!(a[68]&1);$('hwFault').value=a[74]|((a[75]&63)<<8);$('hwDiagMask').value=hex(a[71]&247);msg('Diagnosefelder aus EEPROM-Backup geladen.')});
bind('hwAlarmPrepare',async()=>{if(!/^[0-9a-f]{1,2}$/i.test(val('hwDiagMask')))throw Error('Hex-Maske erforderlich.');if(!confirm('Diagnoseverhalten und Fehlerausgang an entbehrlichem Testchip prüfen?'))return;prepareOnly({diagEnabled:$('hwDiagEnable').checked?1:0,faultDAC:num('hwFault'),diagMask:parseInt(val('hwDiagMask'),16)},'Nur Diagnose')});
$('hwLogAuto').onclick=()=>{if(logTimer){stopLive();return}if(!device?.active){msg('Zuerst verbinden.');return}stopLive();const interval=num('hwLogInterval');if(!Number.isInteger(interval)||interval<250||interval>10000){msg('Intervall 250–10000 ms.');return}$('hwLogAuto').textContent='Intervall-Logging stoppen';logTimer=setInterval(async()=>{if(hwBusy)return;if(log.length>=10000){stopLive();msg('10’000 Zeilen erreicht. Exportieren.');return}hwBusy=true;try{const x=await requireDevice().sample(1);log.push({time:new Date().toISOString(),p:x.p,t:x.t,dac:null,reference:optional('logRef'),temperature:optional('logTemp'),note:val('logNote')+' [OWI]'});renderLog();showSample(x)}catch(e){stopLive();msg(e.message)}finally{hwBusy=false}},interval)};
for(const id of ['hwOutStage','hwRatiometric','hwCap','hwDiagEnable','hwFault','hwDiagMask'])$(id).addEventListener('change',clearPrepared);

function assertWriteGate(){if(!$('hwWriteGate').checked)throw Error('EEPROM-Testschreibfreigabe in Verbindung & Diagnose aktivieren.');requireDevice()}
$('hwWriteGate').onchange=()=>{if(device)device.testWrites=$('hwWriteGate').checked;clearPrepared()};
$('q14Ref').onchange=async()=>{try{if(!q14)throw Error('Modell zuerst berechnen.');const f=$('q14Ref').files[0];if(!f)return;if(f.size>10000)throw Error('Datei zu gross.');const ref=JSON.parse(await f.text());$('q14Compare').textContent=JSON.stringify(compareReference(q14,ref),null,2)}catch(e){msg(e.message)}finally{$('q14Ref').value=''}};
function renderRegisters(){const q=val('registerSearch').toLowerCase();$('registerRows').replaceChildren();if(!registerBytes)return;for(const row of registerRows(registerBytes).filter(x=>[x.address,x.name,x.value].join(' ').toLowerCase().includes(q))){const tr=$('registerRows').insertRow();for(const v of [row.address,row.name,row.value,row.access])cell(tr,v)}}
$('registerSearch').oninput=renderRegisters;
$('dumpFile').addEventListener('change',async()=>{try{const f=$('dumpFile').files[0];if(f?.size===128){registerBytes=new Uint8Array(await f.arrayBuffer());renderRegisters();$('hwDecoded').textContent=JSON.stringify(decodeEEPROM(registerBytes),null,2)}}catch(e){msg(e.message)}});
$('dumpClear').addEventListener('click',()=>{registerBytes=null;renderRegisters();$('hwDecoded').textContent=''});
function renderTrend(){const svg=$('hwTrend'),ns='http://www.w3.org/2000/svg';svg.replaceChildren();const add=(tag,a)=>{const el=document.createElementNS(ns,tag);for(const [k,v] of Object.entries(a))el.setAttribute(k,v);svg.append(el);return el};const y=v=>90-v*75/32768;for(const v of [-25000,0,25000])add('line',{x1:45,x2:595,y1:y(v),y2:y(v),stroke:'currentColor',opacity:.2,'stroke-dasharray':'4 4'});for(const [k,color] of [['p','#236cac'],['t','#b67826']])add('polyline',{points:trend.map((x,i)=>(45+550*i/Math.max(1,trend.length-1))+','+y(x[k])).join(' '),fill:'none',stroke:color,'stroke-width':2});add('text',{x:48,y:13,fill:'#236cac','font-size':11}).textContent='PADC';add('text',{x:100,y:13,fill:'#b67826','font-size':11}).textContent='TADC'}
for(const [id,code] of [['outTest1','outC1'],['outTest2','outC2']])bind(id,async()=>{if(!confirm('Externe Last und Beschaltung geprüft? DAC-Testwert ausgeben?'))return;await requireDevice().testDAC(num(code));msg('DAC-Testwert '+val(code)+' · physisch messen.')});
$('outFit').onclick=guarded(()=>{outFit=outputCalibration({code1:num('outC1'),code2:num('outC2'),actual1:num('outA1'),actual2:num('outA2'),desiredLow:num('outGoal1'),desiredHigh:num('outGoal2')});$('outFitResult').textContent='Zielcodes '+outFit.low+' / '+outFit.high+' · Quantisierungsfehler '+fmt(outFit.lowError)+' / '+fmt(outFit.highError)});
$('outUse').onclick=guarded(()=>{if(!outFit)throw Error('Zielcodes zuerst berechnen.');if(!confirm('Neue DAC-Zielwerte übernehmen? Bestehende Kalibriermesspunkte werden verworfen.'))return;$('dacLow').value=outFit.low;$('dacHigh').value=outFit.high;reset();msg('DAC-Zielcodes übernommen; neuer Abgleich erforderlich.')});
for(const id of ['outC1','outC2','outA1','outA2','outGoal1','outGoal2'])$(id).oninput=()=>{outFit=null;$('outFitResult').textContent=''};
$('hwRestoreFile').onchange=async()=>{restoreBytes=null;clearPrepared();try{const f=$('hwRestoreFile').files[0];if(!f)return;if(f.size!==128)throw Error('128-Byte-Backup erforderlich.');restoreBytes=new Uint8Array(await f.arrayBuffer());if(crc8(restoreBytes.slice(0,127))!==restoreBytes[127]){restoreBytes=null;throw Error('Backup-CRC falsch.')}msg('Backup geladen; noch nichts geschrieben.')}catch(e){msg(e.message)}};
bind('hwRestore',async()=>{assertWriteGate();if(!hwSnapshot||!backupSaved||!restoreBytes)throw Error('Aktuelles EEPROM auslesen und sichern; Restore-Backup laden.');const original=hwSnapshot.bytes.slice(),desired=prepareRestore(original,restoreBytes);if(original.every((v,i)=>v===desired[i]))throw Error('Backup entspricht aktuellem EEPROM.');prepared={original,desired};$('hwDiff').textContent=Array.from(desired,(v,i)=>v===original[i]?null:'0x'+hex(i)+' '+hex(original[i])+' → '+hex(v)).filter(Boolean).join('\n');msg('Wiederherstellung vorbereitet. Nur bei sicher identischem Sensor ausführen.')});
$('coldExit').onclick=()=>$('hwDisconnect').click();
bind('coldCompare',async()=>{if(!postWriteImage||!coldExited)throw Error('Zuerst erfolgreichen Execution-Wechsel durchführen und danach neu verbinden.');if(!confirm('Wurde der Sensor nach Execution-Modus physisch aus- und wieder eingeschaltet?'))return;const x=await requireDevice().readEEPROM();coldMatch=x.decoded.serial===postWriteSerial&&x.chipCRC.good&&x.bytes.every((v,i)=>v===postWriteImage[i]);$('coldStatus').textContent=coldMatch?'EEPROM nach bestätigtem Kaltstart identisch · CRC OK':'Kaltstartvergleich fehlgeschlagen';msg($('coldStatus').textContent)});
$('analogAdd').onclick=guarded(()=>{const row={reference:num('analogRef'),target:num('analogTarget'),actual:num('analogActual')};if(!Object.values(row).every(Number.isFinite))throw Error('Referenz, Soll und Ist erforderlich.');analogRows.push(row);analogResult=null;$('analogResult').textContent=JSON.stringify(analogRows,null,2)});
$('analogCheck').onclick=guarded(()=>{analogResult=verifyAnalog(analogRows,num('analogTol'));$('analogResult').textContent=JSON.stringify(analogResult,null,2);msg(analogResult.pass?'Externe Ausgangsmessung innerhalb Toleranz.':'Externe Ausgangsmessung ausserhalb Toleranz.')});
$('analogClear').onclick=()=>{analogRows=[];analogResult=null;$('analogResult').textContent=''};
