function refreshArchiveSelectors(){const rows=archiveRead();for(const id of ['archiveA','archiveB']){const el=$(id),old=el.value;el.replaceChildren();for(const x of rows){const o=document.createElement('option');o.value=x.id;o.textContent=x.date+' · '+x.type+' · '+(x.sensor||'Ohne ID');el.append(o)}if(rows.some(x=>x.id===old))el.value=old}}
$('archiveFolder').onclick=async()=>{try{if(!window.showDirectoryPicker)throw Error('Ordnerzugriff erfordert unterstützten Chrome/Edge. JSON-Export bleibt verfügbar.');archiveDir=await window.showDirectoryPicker({mode:'readwrite'});$('archiveFolderStatus').textContent='Ordner: '+archiveDir.name+' · Zugriff für diese Sitzung.'}catch(e){if(e.name!=='AbortError')msg(e.message)}};
$('archiveFolderExport').onclick=async()=>{try{if(!archiveDir)throw Error('Archivordner zuerst auswählen.');const rows=archiveRead();if(!rows.length)throw Error('Keine Berichte vorhanden.');const name='PGA300-Archiv-'+new Date().toISOString().replace(/[:.]/g,'-')+'.json';const handle=await archiveDir.getFileHandle(name,{create:true}),w=await handle.createWritable();try{await w.write(JSON.stringify({schema:'pga300-archive-v2',rows},null,2));await w.close()}catch(e){await w.abort().catch(()=>{});throw e}msg('Archivdatei gespeichert: '+name)}catch(e){msg(e.message)}};
$('archiveCompare').onclick=guarded(()=>{const rows=archiveRead(),a=rows.find(x=>x.id===val('archiveA')),b=rows.find(x=>x.id===val('archiveB'));if(!a||!b||a.id===b.id)throw Error('Zwei unterschiedliche Berichte auswählen.');const summarize=x=>({date:x.date,sensor:x.sensor,mode:x.data?.mode,points:x.data?.points?.length??null,maxError:x.data?.fit?.maxError??null,rms:x.data?.fit?.rms??null,verification:x.data?.verification?.pass??null,coldStart:x.data?.coldStartReadback??null,analog:x.data?.analogVerification?.pass??null});$('archiveComparison').textContent=JSON.stringify({A:summarize(a),B:summarize(b),configurationChanges:Object.keys({...a.data?.configuration,...b.data?.configuration}).filter(k=>a.data?.configuration?.[k]!==b.data?.configuration?.[k]).map(k=>({field:k,A:a.data?.configuration?.[k],B:b.data?.configuration?.[k]}))},null,2)});
function printReport(){const w=window.open('','_blank');if(!w){msg('Pop-up blockiert. JSON-Bericht exportieren.');return}const d=w.document;d.title='PGA300 Kalibrierbericht';const style=d.createElement('style');style.textContent='body{font:12px/1.5 Arial,sans-serif;color:#25354a;margin:28px}h1{font-size:24px}h2{font-size:16px;border-bottom:1px solid #b5c2cf;padding-bottom:5px}table{border-collapse:collapse;width:100%;font-size:11px}td,th{border-bottom:1px solid #dce4ed;padding:6px;text-align:left}p{margin:6px 0}section{break-inside:avoid;margin-bottom:16px}@page{margin:15mm}';d.head.append(style);const add=(tag,text,parent=d.body)=>{const e=d.createElement(tag);e.textContent=text;parent.append(e);return e};const table=(heads,rows)=>{const t=d.createElement('table');d.body.append(t);const h=t.insertRow();for(const x of heads)add('th',x,h);for(const row of rows){const tr=t.insertRow();for(const x of row)add('td',String(x??'—'),tr)}};const x=fullReport();add('h1','Texas Instruments · PGA300');add('h2','Kalibrierbericht · Labor-Testversion');add('p','Zeit: '+x.timestamp+' · Sensor: '+(x.sensor||'—')+' · Erfassung: '+x.mode);add('p','Keine Produktionsfreigabe. Modellprüfung ist keine reale Sensorfreigabe.');add('h2','Konfiguration');table(['Parameter','Wert'],Object.entries(x.configuration));add('h2','Kalibriermesspunkte');table(['Referenz','°C','PADC','TADC','DAC Soll','Modellfehler'],x.points.map((p,i)=>[p.pressure,p.temperature,p.p,p.t,p.target,x.fit?.residuals?.[i]]));add('h2','Nachmessung');table(['PADC','TADC','DAC Soll','DAC Ist','Modellfehler'],(x.verificationRows||[]).map((p,i)=>[p.p,p.t,p.target,p.actual,x.verification?.checks?.[i]?.error]));add('p','Kaltstartvergleich: '+(x.coldStartReadback?'identisch':'nicht bestätigt'));add('p','Externe Analogprüfung: '+(x.analogVerification?.pass?'bestanden':'nicht bestätigt / fehlgeschlagen'));if(x.analogVerification)table(['Referenz','Soll','Ist','Fehler'],x.analogVerification.checks.map(p=>[p.reference,p.target,p.actual,p.error]));const b=add('button','Drucken / als PDF speichern');b.onclick=()=>w.print()}
bind('hwGainApplyAuto',async()=>{const dev=requireDevice(),a=await dev.readAFE(),g=recommendGain(num('hwLow'),num('hwHigh'),a.pGain&31);if(!confirm('Gain '+g.gain+' V/V übernehmen? Alle bisherigen Messpunkte verwerfen. Danach beide Druckendpunkte und Temperaturbereich erneut prüfen.'))return;reset();afeApplied=null;const pGain=g.code|((Boolean(a.pGain&128)!==g.invert)?128:0);afeApplied=await dev.setAFE({pGain});loadAFE(afeApplied);$('pg').value=g.gain;$('hwGainAdvice').textContent='Gain '+g.gain+' V/V geschrieben und rückgelesen. Endpunkte neu prüfen.';msg('AFE optimiert; AFE-Bestätigung nach erneuter Endpunktprüfung erforderlich.')});
